-- Costa Rica: milestones + English translations. Hand-written, following
-- the Pakistan/Ecuador/Uruguay pattern. Seven milestones, live-
-- researched against Hacienda's own site (hacienda.go.cr), the official
-- DGT-R-012-2018 resolution text, Costa Rican press (La Nación,
-- Delfino.cr, La Teja, Infobae), and industry tax-technology advisories:
--
-- 1. cr-dgt-r012-2018-announced (2018-03-20, anchor, off-board,
--    mandate_scope='none') -- Resolution DGT-R-012-2018 published in La
--    Gaceta, setting the staggered general-mandate schedule --
--    foundational/procedural, not itself the moment of obligation.
-- 2. cr-general-mandate-wave1-2018 (2018-09-01, on-board, mandate_scope=
--    'b2b') -- first wave of DGT-R-012-2018's staggered schedule
--    (taxpayer ID ending 1/2/3).
-- 3. cr-general-mandate-full-2018 (2018-11-01, on-board, mandate_scope=
--    'b2b') -- final wave (ID ending 0/7/8/9), completing the general
--    mandate -- the flagship/headline milestone for the original rollout.
-- 4. cr-schema-v44-mandatory-2025 (2025-09-01, on-board, mandate_scope=
--    'none') -- XML schema v4.4 becomes mandatory after a coexistence
--    window -- technical schema evolution, not a scope expansion.
-- 5. cr-tribu-cr-launch-2025 (2025-10-06, on-board, mandate_scope=
--    'none') -- Hacienda's new TRIBU-CR platform goes live, replacing
--    ATV -- a platform migration, not a scope change.
-- 6. cr-cedula-cutover-2026 (2026-11-01, on-board, confidence='expected',
--    mandate_scope='none') -- production cutover for the new
--    alphanumeric cédula jurídica format -- a technical ID-format
--    change; marked 'expected' because the exact date is corroborated
--    by a specialized compliance source but not independently confirmed
--    against Hacienda's own primary text in this pass.
-- 7. cr-enforcement-package-2026 (2026-07-23, on-board, mandate_scope=
--    'none') -- a 24-measure tax-enforcement package targeting
--    fraudulent e-invoicing -- enforcement infrastructure, not a scope
--    expansion.
--
-- mandate_scope classification: Costa Rica's general mandate (DGT-R-012-
-- 2018) covers B2B, B2C (via Tiquete Electrónico), and B2G transactions
-- together, so the two 2018 rollout-wave milestones are classified
-- 'b2b' per ADDING-A-COUNTRY.md's definition; the technical/procedural
-- milestones (schema versions, platform migration, ID-format cutover,
-- enforcement infrastructure) are classified 'none'.

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'cr-dgt-r012-2018-announced', id, '2018-03-20', 1, 'https://oaf.ucr.ac.cr/system/files/DGT-R-12-2018.%20Obligatoriedad%20General%20para%20el%20uso%20de%20los%20Comprobantes%20Electr%C3%B3nicos.pdf', 0, '[]', NULL, 'none' FROM countries WHERE code = 'CR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-dgt-r012-2018-announced', 'en', 'Resolution DGT-R-012-2018 sets Costa Rica''s general e-invoicing mandate schedule', 'Signed 19 February 2018 and published in La Gaceta N° 53 (Alcance Digital N° 60) on 20 March 2018, Resolution DGT-R-012-2018 ("Obligatoriedad General para el Uso de los Comprobantes Electrónicos") extended Costa Rica''s existing e-invoicing requirement -- already mandatory for healthcare and other professional-service sectors since January-May 2018 under earlier, sector-specific resolutions -- to essentially all remaining tax-obligated taxpayers, staggered by the last digit of the taxpayer''s ID number. Simplified-Regime (Régimen Simplificado) contributors and certain government/non-profit entities were excluded. Non-compliance was tied to Article 83 of the Código de Normas y Procedimientos Tributarios.', '["No action required for this historical milestone -- it sets the schedule that the two waves below actually deliver", "If your business isn''t sure which wave applied to you, the schedule ran by the last digit of your taxpayer ID number -- see the milestones below for the exact dates"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'cr-general-mandate-wave1-2018', id, '2018-09-01', 0, 'https://oaf.ucr.ac.cr/system/files/DGT-R-12-2018.%20Obligatoriedad%20General%20para%20el%20uso%20de%20los%20Comprobantes%20Electr%C3%B3nicos.pdf', 1, '[{"label": "Hacienda — Comprobantes Electrónicos / TRIBU-CR", "url": "https://www.hacienda.go.cr/AvisosTRIBU-CR.html"}]', NULL, 'b2b' FROM countries WHERE code = 'CR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-general-mandate-wave1-2018', 'en', 'First wave of Costa Rica''s general e-invoicing mandate goes live', 'From 1 September 2018, under DGT-R-012-2018''s staggered schedule, taxpayers whose ID number ends in 1, 2, or 3 became legally required to issue electronic Comprobantes -- the first wave of the general mandate, following healthcare providers and other professional-service sectors who had already been mandated earlier that year. Two further waves followed on 1 October (ID ending 4, 5, or 6) and 1 November 2018 (ID ending 0, 7, 8, or 9), completing the rollout.', '["If your taxpayer ID ends in 1, 2, or 3, confirm your electronic-invoicing obligation has been active since this date", "Choose an invoicing solution now if you haven''t already -- Hacienda''s own free tools and numerous certified third-party providers are both valid paths"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'cr-general-mandate-full-2018', id, '2018-11-01', 0, 'https://oaf.ucr.ac.cr/system/files/DGT-R-12-2018.%20Obligatoriedad%20General%20para%20el%20uso%20de%20los%20Comprobantes%20Electr%C3%B3nicos.pdf', 1, '[{"label": "Hacienda — Comprobantes Electrónicos / TRIBU-CR", "url": "https://www.hacienda.go.cr/AvisosTRIBU-CR.html"}]', NULL, 'b2b' FROM countries WHERE code = 'CR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-general-mandate-full-2018', 'en', 'General e-invoicing mandate completes -- every remaining taxpayer must comply', 'From 1 November 2018, the final wave of DGT-R-012-2018''s schedule brought in every remaining tax-obligated taxpayer whose ID ends in 0, 7, 8, or 9, completing the general mandate that had begun with healthcare and professional services in early 2018 and continued through the September and October waves. Régimen Simplificado contributors and a short list of public-sector/non-profit bodies (for non-commercial activity only) remained excluded. This is the flagship milestone: from this date, electronic invoicing became the default legal requirement for essentially all VAT-registered businesses in Costa Rica, with no revenue threshold.', '["If you haven''t received confirmation your business is issuing compliant electronic Comprobantes, treat this as active non-compliance risk, not a settled legacy question", "Check whether you fall into one of the narrow remaining exemptions (Régimen Simplificado, or non-commercial public-sector/non-profit activity) before assuming the mandate applies to you"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'cr-schema-v44-mandatory-2025', id, '2025-09-01', 0, 'https://www.hacienda.go.cr/docs/ComprobantesElectronicos-GeneralidadesyVersion4.4.marzo2025.pdf', 1, '[{"label": "Hacienda — Comprobantes Electrónicos / TRIBU-CR", "url": "https://www.hacienda.go.cr/AvisosTRIBU-CR.html"}]', NULL, 'none' FROM countries WHERE code = 'CR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-schema-v44-mandatory-2025', 'en', 'XML schema version 4.4 becomes mandatory for all electronic vouchers', 'Following Decree N° 44739-H (8 November 2024) and Resolutions MH-DGT-RES-0027-2024 and MH-DGT-RES-0001-2025, Hacienda opened voluntary adoption of Comprobantes Electrónicos schema version 4.4 on 1 April 2025, ran a coexistence window in which both v4.3 and v4.4 were valid, and made v4.4 mandatory from 1 September 2025. The new version adds payment-method codes (including SINPE Móvil and digital platforms), expanded fields for non-domiciled taxpayers, alcoholic-beverage fiscal-registry integration, more granular tax breakdowns, and enhanced exoneration/exemption documentation.', '["Confirm your invoicing software or provider has certified against schema v4.4 -- v4.3 documents are no longer valid from this date", "If your business handles SINPE Móvil payments, non-domiciled counterparties, or exonerations, check that your v4.4 implementation actually captures the new required fields rather than just passing schema validation"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'cr-tribu-cr-launch-2025', id, '2025-10-06', 0, 'https://www.hacienda.go.cr/AvisosTRIBU-CR.html', 1, '[{"label": "Hacienda — Comprobantes Electrónicos / TRIBU-CR", "url": "https://www.hacienda.go.cr/AvisosTRIBU-CR.html"}]', NULL, 'none' FROM countries WHERE code = 'CR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-tribu-cr-launch-2025', 'en', 'Hacienda launches TRIBU-CR, replacing the ATV platform', 'At 9:00 a.m. on Monday, 6 October 2025, Costa Rica''s Ministerio de Hacienda activated TRIBU-CR (Sistema Integrado de Administración Tributaria), its new integrated tax platform, retiring the old free ATV invoicing tool the previous evening and launching a new free e-invoicing tool, TICO FACTURA, at the same time. The migration moved over 883 million records in the days beforehand. TRIBU-CR''s launch was Phase 1 of a planned 9-phase, 28-module rollout, with full completion targeted for 2027 -- so this is the start of a multi-year platform transition, not a one-off cutover.', '["If you used Hacienda''s free ATV invoicing tool, confirm you''ve migrated to TICO FACTURA -- the old tool was retired the evening before TRIBU-CR went live", "Expect continued rough edges as TRIBU-CR''s remaining 8 phases roll out through 2027 -- monitor Hacienda''s Avisos TRIBU-CR page directly rather than assuming stability"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'cr-cedula-cutover-2026', id, '2026-11-01', 0, 'https://observador.cr/se-acaban-las-cedulas-juridicas-de-costa-rica-bajo-el-formato-actual-nuevo-sistema-incluira-letras/', 1, '[{"label": "Hacienda — Comprobantes Electrónicos / TRIBU-CR", "url": "https://www.hacienda.go.cr/AvisosTRIBU-CR.html"}]', 'expected', 'none' FROM countries WHERE code = 'CR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-cedula-cutover-2026', 'en', 'New alphanumeric cédula jurídica format reaches its e-invoicing production cutover', 'Costa Rica''s National Registry is moving from the current 6-digit numeric cédula jurídica format (e.g. 3-002-662100), whose roughly one million possible combinations are close to exhausted for new company registrations, to a new alphanumeric format (e.g. 3-101-A00001) under Decreto Ejecutivo 44648-MJ. Existing companies keep their current numeric IDs. To support this, Hacienda issued a schema v4.4 technical patch (dated 22 April 2026) adjusting issuer/receiver identification fields to accept alphanumeric characters. Invoicing systems are expected to validate and issue against the new ID format in production from 1 November 2026 -- though the broader cédula rollout timeline has been described elsewhere as not yet fully finalized, so treat this specific date as an expected target rather than a locked, independently-confirmed deadline.', '["If your invoicing system validates taxpayer ID numbers with a fixed 6-digit-numeric pattern, confirm it''s been updated to accept the new alphanumeric cédula jurídica format before this date", "Watch Hacienda''s own TRIBU-CR announcements for final confirmation of this date rather than relying solely on secondary compliance-industry reporting"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence, mandate_scope) SELECT 'cr-enforcement-package-2026', id, '2026-07-23', 0, 'https://www.infobae.com/costa-rica/2026/07/23/costa-rica-presenta-paquete-de-24-medidas-para-fortalecer-el-cobro-de-impuestos-combatir-la-evasion-y-el-contrabando-sin-crear-nuevos-tributos/', 1, '[{"label": "Hacienda — Comprobantes Electrónicos / TRIBU-CR", "url": "https://www.hacienda.go.cr/AvisosTRIBU-CR.html"}]', NULL, 'none' FROM countries WHERE code = 'CR';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cr-enforcement-package-2026', 'en', 'Government unveils a 24-measure package targeting fraudulent e-invoicing', 'Presented 23 July 2026 by President Laura Fernández, Finance Minister Rodrigo Chaves, and Vice Minister Víctor Julio Carvajal, a 24-measure tax-enforcement package directly targets fraudulent electronic invoicing -- "false e-invoice" networks used to under-report tax -- proposing new legal authority for Hacienda to administratively suspend a firm''s e-invoicing rights rather than relying on a lengthy judicial process. The same announcement disclosed the first 10 criminal complaints filed that week against fraudulent-invoice networks, out of more than 400 ongoing investigations, with one disclosed case involving over ₡41 million in improperly reduced tax. This is enforcement infrastructure layered on top of the existing mandate, not a new population being brought into e-invoicing for the first time.', '["Review your invoicing controls and supplier vetting now if your business has any exposure to informal or high-risk suppliers -- Hacienda''s stated focus is specifically on invoice-fraud networks, not routine compliance gaps", "If Hacienda gains the proposed administrative-suspension authority, treat a sudden loss of e-invoicing rights as a real operational risk for any business connected, even indirectly, to a flagged counterparty"]');
